23: function calcularSituacao(atv) {
24:   if (atv._cancelada) return 'cancelada';
25:   const agora = new Date(relogio.agora);
26:   const primeiroInicio = new Date(atv.encontros[0]?.inicio);
27:   const ultimoFim = new Date(atv.encontros[atv.encontros.length - 1]?.fim);
28:   if (agora < primeiroInicio) return 'prevista';
29:   if (agora >= primeiroInicio && agora < ultimoFim) return 'em_andamento';
30:   if (agora >= ultimoFim) return 'encerrada';
31:   return 'prevista';
32: }
