101: // --- POST /atividades ---
102: 
103: app.post('/atividades', (req, res) => {
104:   const { "x-usuario": usuario } = req.headers;
105:   if (!usuario) return res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Usuário não informado' });
106: 
107:   // R1: DADOS_INVALIDOS
108:   if (!req.body || typeof req.body !== 'object') {
109:     return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Corpo inválido' });
110:   }
111:   const { titulo, tipo, salaId, vagas, encontros } = req.body;
112:   if (!titulo || !tipo || !salaId || vagas === undefined || !encontros || !Array.isArray(encontros)) {
113:     return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Campos obrigatórios ausentes ou de tipo errado' });
114:   }
115: 
116:   // R2: QUANTIDADE_DE_ENCONTROS
117:   if (tipo === 'palestra' && encontros.length !== 1) {
118:     return res.status(422).json({ erro: 'QUANTIDADE_DE_ENCONTROS', mensagem: 'Palestra deve ter exatamente 1 encontro' });
119:   }
120:   if (tipo === 'minicurso' && (encontros.length < 2 || encontros.length > 5)) {
121:     return res.status(422).json({ erro: 'QUANTIDADE_DE_ENCONTROS', mensagem: 'Minicurso deve ter entre 2 e 5 encontros' });
122:   }
123: 
124:   // R3: ENCONTRO_INVALIDO
125:   for (const e of encontros) {
126:     if (new Date(e.inicio) >= new Date(e.fim)) {
127:       return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Início deve ser menor que fim' });
128:     }
129:     const duracao = (new Date(e.fim) - new Date(e.inicio)) / 3600000;
130:     if (duracao <= 0 || duracao > 4) {
131:       return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Duração fora do permitido' });
132:     }
133:     const dataInicio = e.inicio.split('T')[0];
134:     const dataFim = e.fim.split('T')[0];
135:     if (dataInicio !== dataFim) {
136:       return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Encontro deve começar e terminar no mesmo dia' });
137:     }
138:     const dtInicio = new Date(e.inicio);
139:     const dtFim = new Date(e.fim);
140:     if (dtInicio < new Date('2026-10-19T00:00:00-03:00') || dtFim > new Date('2026-10-23T23:59:59-03:00')) {
141:       return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Encontro fora do período do evento' });
142:     }
143:     for (const outro of encontros) {
144:       if (outro === e) continue;
145:       if (new Date(e.inicio) < new Date(outro.fim) && new Date(e.fim) > new Date(outro.inicio)) {
146:         return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Encontros da mesma atividade não podem se sobrepor' });
147:       }
148:     }
149:   }
150: 
151:   // R4: VAGAS_ACIMA_DA_CAPACIDADE
152:   const sala = salas.find(s => s.id === salaId);
153:   if (!sala) return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Sala não encontrada' });
154:   if (vagas > sala.capacidade || vagas < 1) {
155:     return res.status(422).json({ erro: 'VAGAS_ACIMA_DA_CAPACIDADE', mensagem: 'Vagas fora do permitido' });
156:   }
157: 
158:   // R5: CONFLITO_DE_SALA
159:   // Na mesma sala, entre o fim de um encontro e o início do seguinte deve haver no mínimo 15 minutos
160:   for (const e of encontros) {
161:     for (const atvAtiva of atividades) {
162:       if (atvAtiva.salaId !== salaId) continue;
163:       for (const ee of atvAtiva.encontros) {
164:         if (calcularSituacao(atvAtiva) === 'cancelada') continue;
165:         // Calcula o gap entre os encontros (em minutos)
166:         const gap1 = (new Date(e.inicio) - new Date(ee.fim)) / 60000; // gap entre fim de ee e início de e
167:         const gap2 = (new Date(ee.inicio) - new Date(e.fim)) / 60000; // gap entre fim de e e início de ee
168:         if ((gap1 >= 0 && gap1 < 15) || (gap2 >= 0 && gap2 < 15)) {
169:           return res.status(409).json({ erro: 'CONFLITO_DE_SALA', mensagem: 'Conflito de sala: menos de 15 minutos de intervalo' });
170:         }
171:       }
172:     }
173:   }
174: 
175:   // Criar atividade
176:   const atividade = {
177:     id: `atv_${String(proximoId++).padStart(8, '0')}`,
178:     titulo,
179:     tipo,
180:     salaId,
181:     vagas,
182:     encontros: encontros.map(e => ({
183:       id: `enc_${String(Math.floor(Math.random() * 0xFFFFFFFF)).toString(16).padStart(8, '0')}`,
184:       inicio: e.inicio,
185:       fim: e.fim
186:     })),
187:     cargaHorariaMinutos: encontros.reduce((acc, e) => acc + (new Date(e.fim) - new Date(e.inicio)) / 60000, 0),
188:     ocupadas: 0,
189:     vagasRestantes: vagas,
190:     emEspera: 0
191:   };
192: 
193:   atividades.push(atividade);
194:   res.status(201).json(atividadeResponse(atividade));
195: });
