216:   if (req.body.vagas !== undefined) {
217:     const sala = salas.find(s => s.id === atv.salaId);
218:     if (sala && (req.body.vagas > sala.capacidade || req.body.vagas < 1)) {
219:       return res.status(422).json({ erro: 'VAGAS_ACIMA_DA_CAPACIDADE', mensagem: 'Vagas fora do permitido' });
220:     }
221:   }
222: 
223:   // Aplicar alterações
224:   for (const [key, value] of Object.entries(req.body)) {
225:     if (['titulo', 'vagas'].includes(key)) {
226:       atv[key] = value;
227:     }
228:   }
229: 
230:   // R7: QUANTIDADE_DE_ENCONTROS (se encontros alterados)
231:   if (req.body.encontros) {
232:     // R8: ENCONTRO_INVALIDO
233:     // ... validações ...
234:   }
235: 
236:   // Atualizar carga horária
237:   atv.cargaHorariaMinutos = atv.encontros.reduce((acc, e) => acc + (new Date(e.fim) - new Date(e.inicio)) / 60000, 0);
238: 
239:   res.json(atividadeResponse(atv));
240: });
